function solve({config,state,event}){
  if(state===null){state={seq:0,log:[],acks:{},view:{}};for(const r of config.readers)state.acks[r]=0;}
  const t=event.type;
  if(t==='set'){
    state.seq++;
    state.log.push({seq:state.seq,key:event.key,value:event.value});
    state.view[event.key]=event.value;
  }else if(t==='ack'){
    const old=state.acks[event.reader];
    if(old!==undefined&&old<=event.seq&&event.seq<=state.seq)state.acks[event.reader]=event.seq;
  }else if(t==='compact'){
    let wm=Infinity;
    for(const r of config.readers)if(state.acks[r]<wm)wm=state.acks[r];
    const latest={};
    for(const rec of state.log)if(rec.seq<=wm)latest[rec.key]=rec;
    const kept=[];
    for(const rec of state.log)if(rec.seq>wm||latest[rec.key]===rec)kept.push(rec);
    state.log=kept;
  }
  return {state,output:{log:state.log.map(r=>r.seq),view:{...state.view}}};
}
